<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue';import type{ColDef}from'ag-grid-community';import{ElMessage,ElMessageBox}from'element-plus';import AppDataGrid from'@/components/AppDataGrid.vue';import{deleteDNSProvider,getDNSProvider,listDNSProviders,saveDNSProvider,testDNSProvider,type SSLDNSProvider}from'@/api/ssl-cert';import{useAuthStore}from'@/stores/auth'
const auth=useAuthStore(),rows=ref<SSLDNSProvider[]>([]),keyword=ref(''),provider=ref(''),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),dialog=ref(false);const empty=()=>({id:undefined as number|undefined,name:'',provider:'aliyun',config:'{}',email:'',phone:'',enabled:true});const form=reactive(empty())
async function load(){loading.value=true;try{const{data}=await listDNSProviders({keyword:keyword.value,provider:provider.value,page:page.value,limit:pageSize.value});rows.value=data.data.list;total.value=data.data.total}finally{loading.value=false}}
async function open(row?:SSLDNSProvider){Object.assign(form,empty());if(row){const{data}=await getDNSProvider(row.id);Object.assign(form,data.data)}dialog.value=true}async function save(){if(!form.name.trim())return ElMessage.warning('请输入配置名称');await saveDNSProvider(form);dialog.value=false;ElMessage.success('保存成功');await load()}async function remove(row:SSLDNSProvider,confirm=true){if(confirm)await ElMessageBox.confirm(`确认删除“${row.name}”吗？`,'删除确认',{type:'warning'});await deleteDNSProvider(row.id)}async function bulkDelete(items:unknown[]){await ElMessageBox.confirm(`确认删除选中的 ${items.length} 项吗？`,'批量删除',{type:'warning'});for(const row of items as SSLDNSProvider[])await remove(row,false);await load()}async function test(row:SSLDNSProvider){await testDNSProvider(row.id);ElMessage.success('配置验证通过');await load()}
function actions(p:{data:SSLDNSProvider}){const w=document.createElement('div');w.className='ssl-actions';const add=(t:string,c:string,f:()=>void)=>{const b=document.createElement('button');b.textContent=t;b.className=c;b.onclick=f;w.append(b)};if(auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/test'))add('测试','ssl-test',()=>void test(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/save'))add('编辑','ssl-edit',()=>void open(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/delete'))add('删除','ssl-delete',()=>void remove(p.data).then(load));return w}
const columns=computed<ColDef[]>(()=>[{headerName:'序号',width:64,valueGetter:p=>(page.value-1)*pageSize.value+(p.node?.rowIndex||0)+1},{field:'name',headerName:'配置名称',minWidth:150},{field:'provider',headerName:'DNS 服务商',minWidth:120},{field:'email',headerName:'联系邮箱',minWidth:160,valueFormatter:p=>p.value||'-'},{field:'enabled',headerName:'状态',width:85,valueFormatter:p=>p.value?'启用':'停用'},{field:'last_test_ok',headerName:'最近测试',width:100,valueFormatter:p=>p.data.last_test_at?(p.value?'通过':'失败'):'未测试'},{headerName:'操作',pinned:'right',width:200,cellRenderer:actions}]);watch([keyword,provider],()=>{page.value=1;void load()});onMounted(load)
</script>
<template><section class="ssl-page"><header><h2>DNS 配置</h2><p>维护 ACME DNS 验证所需的服务商凭据。</p></header><div class="toolbar"><div class="filters"><el-input v-model="keyword" placeholder="搜索配置名称" clearable/><el-select v-model="provider" placeholder="选择 DNS 服务商" clearable><el-option label="阿里云 DNS" value="aliyun"/><el-option label="Cloudflare" value="cloudflare"/><el-option label="华为云 DNS" value="huawei"/><el-option label="AWS Route53" value="aws_route53"/></el-select></div><el-button v-permission="'POST /api/v1/ssl-cert/dns-providers/save'" type="primary" @click="open()">新增 DNS 配置</el-button></div><AppDataGrid v-loading="loading" class="grid" :row-data="rows" :column-defs="columns" pagination server-pagination :total="total" :current-page="page" :page-size="pageSize" :bulk-delete="auth.hasPermission('POST /api/v1/ssl-cert/dns-providers/delete')?bulkDelete:undefined" @page-change="v=>{page=v;void load()}" @page-size-change="v=>{pageSize=v;page=1;void load()}"/><el-dialog v-model="dialog" :title="form.id?'编辑 DNS 配置':'新增 DNS 配置'" width="620px"><el-form label-width="90px"><el-form-item label="配置名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="服务商" required><el-select v-model="form.provider" style="width:100%"><el-option label="阿里云 DNS" value="aliyun"/><el-option label="Cloudflare" value="cloudflare"/><el-option label="华为云 DNS" value="huawei"/><el-option label="AWS Route53" value="aws_route53"/></el-select></el-form-item><el-form-item label="配置 JSON" required><el-input v-model="form.config" type="textarea" :rows="8" placeholder="请输入服务商凭据 JSON"/></el-form-item><div class="form-row"><el-form-item label="联系邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone"/></el-form-item></div><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.ssl-page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;padding:0 4px;font-size:11px}header h2{margin:0;font-size:20px}header p{margin:3px 0 0;color:var(--text-soft)}.toolbar{display:flex;justify-content:space-between;gap:8px}.filters{display:flex;gap:6px}.filters .el-input{width:150px}.filters .el-select{width:150px}.grid{flex:1;min-height:0}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}:deep(.ssl-actions){height:100%;display:flex;align-items:center;gap:5px}:deep(.ssl-actions button){height:26px;border-radius:8px;padding:3px 8px;background:#fff;cursor:pointer}:deep(.ssl-edit){border:1px solid var(--primary);color:var(--primary)}:deep(.ssl-test){border:1px solid #7bcf91;color:#27ae60}:deep(.ssl-delete){border:1px solid #f3b4b4;color:var(--danger)}</style>
